contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address target, uint256 amount) internal {
        vm.assume(address(c).balance >= amount);
        uint beforeBal = address(c).balance;
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        bool reverted;
        try c.sendMoney(target, amount) { reverted = false; } catch { reverted = true; }
        uint afterBal = address(c).balance;
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        assertTrue(reverted ? (afterBal == beforeBal && afterCount == beforeCount) : (afterBal == beforeBal - amount && afterCount == beforeCount));
